#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int x[105];
    int max_h = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &x[i]);
        if (x[i] > max_h) {
            max_h = x[i];
        }
    }

    // A linha superior corresponde ao nível max_h, descendo até 1 na base
    for (int h = max_h; h >= 1; h--) {
        for (int i = 0; i < n; i++) {
            if (x[i] >= h) {
                printf("1");
            } else {
                printf("0");
            }
            if (i < n - 1) {
                printf(" ");
            }
        }
        printf("\n");
    }

    return 0;
}
